// Standalone native MPEG fixture. Requires ICON1.PMF and SND0.AT3 from your own disc;
// no copyrighted media is embedded in this source or generated by the fixture.
#include "../host/mpeg_runtime.hpp"
#include "../host/av_runtime.hpp"
#include "../host/thread_runtime.hpp"
#include "vcs_media_decoder.hpp"
#include <algorithm>
#include <array>
